package main

import (
	_ "embed"
	"encoding/binary"
	"fmt"
)

// Generated by tools/freeze_gamesdb.py from a matching CDN index and bundles.
// Only public catalog metadata is embedded, not accounts or login captures.
//
//go:embed gamesdb_snapshot.bin
var gamesDBSnapshot []byte

type catalogObject struct {
	id, change uint32
	compressed []byte
}

type frozenCatalog struct {
	headers []byte
	objects []catalogObject
	byID    map[uint32]catalogObject
}

func parseCatalog(data []byte) (*frozenCatalog, error) {
	if len(data) < 12 {
		return nil, fmt.Errorf("short catalog header")
	}
	c := &frozenCatalog{headers: data[:12], byID: make(map[uint32]catalogObject)}
	var sum, latest, previous uint32
	for rest := data[12:]; len(rest) > 0; {
		if len(rest) < 12 {
			return nil, fmt.Errorf("short object header")
		}
		id, change, size := binary.BigEndian.Uint32(rest), binary.BigEndian.Uint32(rest[4:]), binary.BigEndian.Uint32(rest[8:])
		rest = rest[12:]
		if id <= previous || size == 0 || uint64(size) > uint64(len(rest)) {
			return nil, fmt.Errorf("invalid object %d", id)
		}
		o := catalogObject{id, change, rest[:size]}
		c.objects = append(c.objects, o)
		c.byID[id] = o
		rest = rest[size:]
		sum += id
		previous = id
		if change > latest {
			latest = change
		}
	}
	if sum != binary.BigEndian.Uint32(data) || uint64(len(c.objects)) != uint64(binary.BigEndian.Uint32(data[4:])) || latest != binary.BigEndian.Uint32(data[8:]) {
		return nil, fmt.Errorf("catalog fingerprints disagree with objects")
	}
	return c, nil
}

var localCatalog = func() *frozenCatalog {
	c, err := parseCatalog(gamesDBSnapshot)
	if err != nil {
		panic(err)
	}
	return c
}()

func gamesDBResponse(request []byte) ([]byte, string) {
	if len(request) < 9 || request[0] != 18 || binary.LittleEndian.Uint32(request[1:5]) != uint32(len(request)-5) {
		return nil, "malformed"
	}
	p := append([]byte(nil), request[:9]...)
	kind := ""
	switch binary.BigEndian.Uint32(request[5:]) {
	case 0xac7766d8:
		if len(request) != 9 {
			return nil, "malformed-state"
		}
		p = append(p, localCatalog.headers...)
		kind = "frozen-state"
	case 0x08775d76:
		if len(request) != 13 {
			return nil, "malformed-index"
		}
		cursor := binary.BigEndian.Uint32(request[9:])
		p = append(p, localCatalog.headers...)
		for _, o := range localCatalog.objects {
			if o.change > cursor {
				p = appendU32(p, o.id)
				p = appendU32(p, o.change)
			}
		}
		kind = "frozen-index"
	case 0xba50633d:
		if len(request) < 13 || (len(request)-9)%4 != 0 {
			return nil, "malformed-game-page"
		}
		for offset := 9; offset < len(request); offset += 4 {
			id := binary.BigEndian.Uint32(request[offset:])
			o, exists := localCatalog.byID[id]
			size := 5
			if exists {
				size += 8 + len(o.compressed)
			}
			if size > maxQueuedBytes-len(p) {
				return nil, "object-batch-exceeds-output-limit"
			}
			p = appendU32(p, id)
			if !exists {
				p = append(p, 0)
				continue
			}
			p = append(p, 1)
			p = appendU32(p, o.change)
			p = appendU32(p, uint32(len(o.compressed)))
			p = append(p, o.compressed...)
		}
		kind = "frozen-objects"
	default:
		return nil, "unsupported-command"
	}
	binary.LittleEndian.PutUint32(p[1:5], uint32(len(p)-5))
	return p, kind
}
